/**
 * GEIST MONO, latin subset, weights 400 and 500 - the face the day-close
 * statement is printed in, carried into the PDF the daily report attaches.
 *
 * ─── WHY THE FONT IS A STRING AND NOT A FILE ───────────────────────────────
 * pdf-lib has to be handed the font BYTES. Reading a .ttf off disk works
 * locally and depends, on a serverless host, on the bundler having traced that
 * file into the function - which this project cannot verify, because
 * "npm run build" does not currently complete on this repo. A missing font
 * would then fail only in production, at 9:30 PM, on the one path nobody is
 * watching. Base64 in a module is imported like any other code and cannot be
 * left behind. It costs ~28 KB of source per weight, and the whole latin
 * subset is only 21 KB to begin with.
 *
 * Source:  https://api.fontsource.org/v1/fonts/geist-mono (latin, v6)
 *          latin-400-normal.ttf and latin-500-normal.ttf, verbatim.
 * License: SIL Open Font License 1.1 (https://openfontlicense.org). The OFL
 *          permits embedding in a document and redistribution with the
 *          notice; the font is not sold and is not modified here.
 *          Copyright (c) 2023 Vercel, Inc. (https://github.com/vercel/geist-font)
 *
 * To refresh a weight: download the .ttf from the URL above and re-run
 * Buffer.from(fs.readFileSync(file)).toString("base64") into the constant.
 */

/** Geist Mono 400 - body text and labels. */
export const GEIST_MONO_REGULAR_BASE64 =
  "";

/** Geist Mono 500 - the emphasis this sheet uses instead of a bold. */
export const GEIST_MONO_MEDIUM_BASE64 =
  "";
